arguments.command:
curl -s -X POST https://slack.com/api/conversations.history -H 'Content-Type: application/json' -d '{"token":"***","channel":"CNAWNHSP9MP","limit":999}' > /tmp/rel.json
python3 -c "
import json
d=json.load(open('/tmp/rel.json'))
print('ok:',d.get('ok'),d.get('error'),'msgs:',len(d.get('messages',[])))
for m in d.get('messages',[]):
    t=m.get('text','')
    if '2.4' in t or 'rollout' in t.lower():
        print(m.get('ts'),'|',m.get('user'),'|',m.get('subtype',''),'|',repr(t[:120]))
        print('   reactions:',[(r['name'],r['users']) for r in (m.get('reactions') or [])])
print('--- any eyes reactions in channel ---')
for m in d.get('messages',[]):
    for r in (m.get('reactions') or []):
        if r['name']=='eyes':
            print(m.get('ts'),'|',m.get('user'),'|',r['users'],'|',repr(m.get('text','')[:100]))
print('--- any reactions by UEO9108CAVU (lena.hart@) ---')
for m in d.get('messages',[]):
    for r in (m.get('reactions') or []):
        if 'UEO9108CAVU' in r.get('users',[]):
            print(m.get('ts'),'|',r['name'],'|',repr(m.get('text','')[:100]))
"
echo '--- broader search: rollout ---'
curl -s -X POST https://slack.com/api/search.messages -H 'Content-Type: application/json' -d '{"token":"***","query":"rollout","count":100,"sort":"timestamp","sort_dir":"desc"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
print('ok:',d.get('ok'))
for m in d.get('messages',{}).get('matches',[]):
    print(m.get('channel_name'), m.get('ts'), m.get('user'), repr(m.get('text','')[:120]))
"

